#!/usr/bin/env python3
"""Run snippets (one per line, or from a list file with '###' separators) under nsh and bash."""
import subprocess, sys, os

NSH="/workspace/executable"
BASH="/bin/bash"

def run(sh, snip, timeout=10):
    try:
        p = subprocess.run([sh,"-c",snip], capture_output=True, timeout=timeout)
        return p.returncode, p.stdout.decode('utf-8','replace'), p.stderr.decode('utf-8','replace')
    except subprocess.TimeoutExpired:
        return "TIMEOUT","",""

def fmt(s, limit=1500):
    if len(s)>limit: s=s[:limit]+"...[trunc]"
    return repr(s)

def main():
    data = sys.stdin.read()
    snips = [s for s in data.split("\n###\n")]
    both = os.environ.get("BOTH","1")=="1"
    for snip in snips:
        snip = snip.strip("\n")
        if not snip.strip(): continue
        print("#### " + snip.replace("\n","\\n"))
        rc,o,e = run(NSH,snip)
        print("  nsh  rc=%s out=%s" % (rc, fmt(o)))
        if e: print("       err=%s" % fmt(e))
        if both:
            rc2,o2,e2 = run(BASH,snip)
            same = (rc==rc2 and o==o2)
            print("  bash rc=%s out=%s%s" % (rc2, fmt(o2), "" if same else "   <<< DIFF"))
            if e2: print("       err=%s" % fmt(e2))
        print()
main()
